/**
 * Builds code tokens from the Figma variable snapshot (tokens/figma-variables.json).
 *
 * Outputs (all generated — do not edit by hand):
 *   src/styles/tokens.css          CSS variables, named exactly like Figma's code syntax, for all 4 modes
 *   src/styles/tailwind-theme.css  Tailwind v4 @theme that exposes the tokens as utility classes
 *   docs/tokens.md                 Human/agent-readable token reference
 *
 * Run: npm run tokens
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

type Value = string | number | boolean | { alias: string };
interface Variable {
  name: string;
  type: "COLOR" | "FLOAT" | "STRING" | "BOOLEAN";
  css: string | null;
  description: string;
  scopes: string[];
  values: Record<string, Value>;
}
interface Collection {
  modes: string[];
  variables: Variable[];
}
interface TextStyle {
  name: string;
  description: string;
  fontFamily: string;
  fontStyle: string;
  fontSize: number;
  lineHeight: number | null;
  /** Figma letter spacing in percent of the font size (Figma unit PERCENT). */
  letterSpacing: number;
  fontSizeVar: string | null;
  lineHeightVar: string | null;
}
interface EffectStyle {
  name: string;
  description: string;
  effects: { type: string; x: number; y: number; blur: number; spread: number; colorVar: string | null; color?: string }[];
}
interface Snapshot {
  collections: Record<string, Collection>;
  textStyles: TextStyle[];
  effectStyles: EffectStyle[];
}

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const snap: Snapshot = JSON.parse(readFileSync(resolve(root, "tokens/figma-variables.json"), "utf8"));

const PRIMITIVES = "Startline / Primitives";
const COLOUR = "Startline / Colour";
const LAYOUT = "Startline / Layout";
const TYPE = "Startline / Typography";

/** Mode name in Figma → data-theme value in code. */
export const THEMES = { Light: "light", Dark: "dark", "IC - Light": "ic-light", "IC - Dark": "ic-dark" } as const;
/** Figma variables that exist only for device mock-ups and are left out of code. */
const EXCLUDED = new Set(["System/Dynamic Island"]);

export const kebab = (s: string) =>
  s
    .replace(/([a-z])([A-Z])/g, "$1-$2")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** CSS variable name for a Figma variable: its code syntax if set, otherwise --startline-<kebab>. */
export const cssVar = (v: Pick<Variable, "name" | "css">) =>
  v.css ? v.css.replace(/^var\((.*)\)$/, "$1") : `--startline-${kebab(v.name)}`;

const all = Object.values(snap.collections).flatMap((c) => c.variables);
const byName = new Map(all.map((v) => [v.name, v]));

const px = (n: number) => (n === 0 ? "0" : `${n}px`);
function render(v: Variable, value: Value): string {
  if (typeof value === "object" && value !== null && "alias" in value) {
    const target = byName.get(value.alias);
    if (!target) throw new Error(`${v.name}: alias to unknown variable "${value.alias}"`);
    return `var(${cssVar(target)})`;
  }
  if (v.type === "FLOAT" && typeof value === "number") return px(value);
  return String(value);
}

const coll = (name: string) => {
  const c = snap.collections[name];
  if (!c) throw new Error(`Missing collection "${name}" in snapshot`);
  return c;
};
const decls = (vars: Variable[], mode: string, indent = "  ") =>
  vars
    .filter((v) => !EXCLUDED.has(v.name))
    .map((v) => {
      const value = v.values[mode];
      if (value === undefined) throw new Error(`${v.name}: no value for mode "${mode}"`);
      return `${indent}${cssVar(v)}: ${render(v, value)};`;
    })
    .join("\n");

const prim = coll(PRIMITIVES);
const colour = coll(COLOUR);
const single = [coll(LAYOUT), coll(TYPE)];
const sortByName = (vs: Variable[]) => [...vs].sort((a, b) => a.name.localeCompare(b.name, "en", { numeric: true }));

const block = (selector: string, mode: string, scheme: "light" | "dark", indent = "") =>
  `${indent}${selector} {\n${indent}  color-scheme: ${scheme};\n${decls(sortByName(colour.variables), mode, indent + "  ")}\n${indent}}`;

const banner = `/* GENERATED by scripts/build-tokens.ts from tokens/figma-variables.json — do not edit. */\n`;

// ---------- tokens.css ----------
const tokensCss = `${banner}
/* Primitives and fixed scales (same in every theme). */
:root {
${decls(sortByName(prim.variables), "Value")}
${single.map((c) => decls(sortByName(c.variables), "Value")).join("\n")}
  /* Brand font first; each script falls back to a matching Noto (bundled) or the device's CJK font. */
  --startline-font-family: "Plus Jakarta Sans", "Noto Sans Arabic", "Noto Sans Ethiopic", "Noto Sans Devanagari",
    "Noto Sans Bengali", "Noto Sans Gurmukhi", "PingFang SC", "Hiragino Sans", "Apple SD Gothic Neo",
    "Microsoft YaHei", "Yu Gothic UI", "Malgun Gothic", "Noto Sans CJK SC", system-ui, sans-serif;
}

/* Semantic colours. Default = Light; follows the device when no data-theme is set. */
${block(":root, [data-theme=\"light\"]", "Light", "light")}

@media (prefers-color-scheme: dark) {
${block(":root:not([data-theme])", "Dark", "dark", "  ")}
}

@media (prefers-contrast: more) {
${block(":root:not([data-theme])", "IC - Light", "light", "  ")}
}

@media (prefers-contrast: more) and (prefers-color-scheme: dark) {
${block(":root:not([data-theme])", "IC - Dark", "dark", "  ")}
}

/* Explicit themes: set data-theme on <html> or any wrapper. */
${block('[data-theme="dark"]', "Dark", "dark")}

${block('[data-theme="ic-light"]', "IC - Light", "light")}

${block('[data-theme="ic-dark"]', "IC - Dark", "dark")}
`;

// ---------- tailwind-theme.css ----------
const colourUtil = (v: Variable) => `  --color-${kebab(v.name)}: var(${cssVar(v)});`;
const radius = coll(LAYOUT).variables.filter((v) => v.name.startsWith("Radius/"));
const radiusKey = (n: string) => ({ None: "none", Pill: "full" })[n] ?? kebab(n);
const controls = coll(LAYOUT).variables.filter((v) => /^(Control|Avatar)\//.test(v.name));
const weight: Record<string, number> = { Regular: 400, Medium: 500, SemiBold: 600, "Semi Bold": 600, Bold: 700, ExtraBold: 800 };
const textKey = (name: string) => kebab(name.replace(/^Startline\s*\/\s*/, ""));
const varOf = (name: string | null) => (name && byName.get(name) ? `var(${cssVar(byName.get(name)!)})` : null);

const tailwindCss = `${banner}
/*
 * Exposes Startline tokens as Tailwind utilities. Every value points at a token variable,
 * so switching data-theme recolours everything without new classes.
 *   bg-surface-primary  text-text-secondary  border-border-default  bg-action-primary
 *   p-4 (= Spacing/4 = 16px)  rounded-md (= Radius/MD)  h-control-lg  text-body  shadow-raised
 */
@theme inline {
  --font-sans: var(--startline-font-family);

  /* Spacing: Tailwind's scale × 4 px = Figma Spacing/N (p-1.5 = Spacing/1-5 = 6px). */
  --spacing: var(--startline-spacing-1);

  /* Colours (Figma Startline / Colour → --color-<group>-<name>) */
${sortByName(colour.variables.filter((v) => !EXCLUDED.has(v.name))).map(colourUtil).join("\n")}

  /* Radius */
${radius.map((v) => `  --radius-${radiusKey(v.name.split("/")[1]!)}: var(${cssVar(v)});`).join("\n")}

  /* Control and avatar sizes: h-control-lg, size-avatar-md … */
${controls.map((v) => `  --spacing-${kebab(v.name)}: var(${cssVar(v)});`).join("\n")}

  /* Text styles (Figma text styles → text-<name>) */
${snap.textStyles
  .map((s) => {
    const k = textKey(s.name);
    return [
      `  --text-${k}: ${varOf(s.fontSizeVar) ?? px(s.fontSize)};`,
      `  --text-${k}--line-height: ${varOf(s.lineHeightVar) ?? (s.lineHeight ? px(s.lineHeight) : "normal")};`,
      `  --text-${k}--font-weight: ${weight[s.fontStyle] ?? 400};`,
      s.letterSpacing ? `  --text-${k}--letter-spacing: ${s.letterSpacing / 100}em;` : "",
    ]
      .filter(Boolean)
      .join("\n");
  })
  .join("\n")}

  /* Elevation (Figma effect styles) */
${snap.effectStyles
  .map(
    (s) =>
      `  --shadow-${textKey(s.name).replace(/^elevation-/, "")}: ${s.effects
        .map((e) => `${px(e.x)} ${px(e.y)} ${px(e.blur)} ${px(e.spread)} ${varOf(e.colorVar) ?? e.color ?? "rgb(0 0 0 / 0.12)"}`)
        .join(", ")};`,
  )
  .join("\n")}
}
`;

// ---------- docs/tokens.md ----------
const resolveHex = (v: Variable, mode: string): string => {
  const val = v.values[mode] ?? v.values["Value"];
  if (typeof val === "object" && val && "alias" in val) {
    const t = byName.get(val.alias)!;
    return `${val.alias} (${resolveHex(t, "Value")})`;
  }
  return String(val);
};
const md = `<!-- GENERATED by scripts/build-tokens.ts — do not edit. -->
# Startline tokens

Source: Figma \`Startline\` variables. Regenerate with \`npm run tokens\`.
Use **semantic colour tokens** (below) in components — never primitives or raw hex.

## Colour (semantic)

| Figma token | Tailwind | CSS variable | Light | Dark | Use for |
|---|---|---|---|---|---|
${sortByName(colour.variables.filter((v) => !EXCLUDED.has(v.name)))
  .map(
    (v) =>
      `| ${v.name} | \`*-${kebab(v.name)}\` | \`${cssVar(v)}\` | ${resolveHex(v, "Light")} | ${resolveHex(v, "Dark")} | ${v.description} |`,
  )
  .join("\n")}

Themes: \`light\` (default), \`dark\`, \`ic-light\`, \`ic-dark\` (high contrast) via \`data-theme\`, or automatic from the device.

## Spacing, radius, sizes

| Figma token | Value | Tailwind | Use for |
|---|---|---|---|
${sortByName(coll(LAYOUT).variables)
  .map((v) => {
    const n = v.values["Value"] as number;
    const tw = v.name.startsWith("Spacing/")
      ? `p-${v.name.split("/")[1]!.replace("-", ".")}, gap-…`
      : v.name.startsWith("Radius/")
        ? `rounded-${radiusKey(v.name.split("/")[1]!)}`
        : /^(Control|Avatar)\//.test(v.name)
          ? `h-${kebab(v.name)} / size-${kebab(v.name)}`
          : "—";
    return `| ${v.name} | ${n}px | \`${tw}\` | ${v.description} |`;
  })
  .join("\n")}

## Text styles

| Figma style | Tailwind | Font | Size / line height | Use for |
|---|---|---|---|---|
${snap.textStyles
  .map(
    (s) =>
      `| ${s.name} | \`text-${textKey(s.name)}\` | ${s.fontFamily} ${s.fontStyle} | ${s.fontSize}/${s.lineHeight}px | ${s.description} |`,
  )
  .join("\n")}

## Elevation

| Figma style | Tailwind |
|---|---|
${snap.effectStyles.map((s) => `| ${s.name} | \`shadow-${textKey(s.name).replace(/^elevation-/, "")}\` |`).join("\n")}
`;

// ---------- native/tokens.ts (React Native / Expo) ----------
// The same Figma values as plain numbers and hex strings, for apps that can't use CSS variables.
const camel = (s: string) =>
  s
    .replace(/^Startline\s*\/\s*/, "")
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((w, i) => (i === 0 ? w.charAt(0).toLowerCase() + w.slice(1) : w.charAt(0).toUpperCase() + w.slice(1)))
    .join("");
const hexOf = (v: Variable, mode: string): string => {
  const val = v.values[mode] ?? v.values["Value"];
  if (typeof val === "object" && val && "alias" in val) return hexOf(byName.get(val.alias)!, "Value");
  return String(val);
};
const scaleKey = (name: string) => name.split("/")[1]!.replace("-", ".").toLowerCase();
const scale = (prefix: string) =>
  Object.fromEntries(
    sortByName(all.filter((v) => v.name.startsWith(prefix))).map((v) => [scaleKey(v.name), v.values["Value"] as number]),
  );
const NATIVE_THEMES = { light: "Light", dark: "Dark", icLight: "IC - Light", icDark: "IC - Dark" } as const;
const themeColours = (mode: string) =>
  Object.fromEntries(
    sortByName(colour.variables.filter((v) => !EXCLUDED.has(v.name))).map((v) => [camel(v.name), hexOf(v, mode)]),
  );
/** rgb(12 31 30 / 0.07) or #rrggbbaa → { rgb: '#rrggbb', alpha } */
const splitColour = (c: string): { rgb: string; alpha: number } => {
  const m = /^rgb\((\d+) (\d+) (\d+) \/ ([\d.]+)\)$/.exec(c);
  if (m) {
    const h = (n: string) => Number(n).toString(16).padStart(2, "0");
    return { rgb: `#${h(m[1]!)}${h(m[2]!)}${h(m[3]!)}`, alpha: Number(m[4]) };
  }
  const hex = c.replace("#", "");
  return { rgb: `#${hex.slice(0, 6)}`, alpha: hex.length === 8 ? Math.round((parseInt(hex.slice(6), 16) / 255) * 100) / 100 : 1 };
};
const shadowsFor = (mode: string) =>
  Object.fromEntries(
    snap.effectStyles.map((s) => {
      const layers = s.effects.map((e) => {
        const raw = e.colorVar ? hexOf(byName.get(e.colorVar)!, mode) : (e.color ?? "rgb(0 0 0 / 0.12)");
        return { ...e, ...splitColour(raw) };
      });
      const main = layers.reduce((a, b) => (b.blur > a.blur ? b : a));
      const boxShadow = layers
        .map((l) => `${l.x}px ${l.y}px ${l.blur}px ${l.spread}px ${l.rgb}${Math.round(l.alpha * 255).toString(16).padStart(2, "0")}`)
        .join(", ");
      return [
        camel(s.name).replace(/^elevation/, "").replace(/^./, (c) => c.toLowerCase()),
        {
          boxShadow,
          shadowColor: main.rgb,
          shadowOpacity: main.alpha,
          shadowRadius: main.blur,
          shadowOffset: { width: main.x, height: main.y },
          elevation: Math.max(1, Math.round(main.blur / 3)),
        },
      ];
    }),
  );
const rnWeight: Record<number, string> = { 400: "400Regular", 500: "500Medium", 600: "600SemiBold", 700: "700Bold", 800: "800ExtraBold" };
const textStylesNative = Object.fromEntries(
  snap.textStyles.map((s) => [
    camel(s.name),
    {
      fontFamily: `PlusJakartaSans_${rnWeight[weight[s.fontStyle] ?? 400]}`,
      fontSize: s.fontSize,
      lineHeight: s.lineHeight ?? Math.round(s.fontSize * 1.4),
      letterSpacing: Math.round(((s.letterSpacing * s.fontSize) / 100) * 100) / 100,
    },
  ]),
);
const json = (o: unknown) => JSON.stringify(o, null, 2);
const nativeTs = `// GENERATED by scripts/build-tokens.ts from tokens/figma-variables.json — do not edit.
// Startline tokens for React Native / Expo. Figma is the source of truth: change Figma, run \`npm run tokens\`.
// Font names match @expo-google-fonts/plus-jakarta-sans.

/** Raw palette. Prefer the semantic colours in \`themes\`. */
export const primitives = ${json(Object.fromEntries(sortByName(prim.variables).map((v) => [camel(v.name), hexOf(v, "Value")])))} as const;

/** Semantic colours per theme (Figma Startline / Colour modes). Pick by meaning, not by look. */
export const themes = {
${Object.entries(NATIVE_THEMES)
  .map(([k, mode]) => `  ${k}: ${json(themeColours(mode)).replace(/\n/g, "\n  ")}`)
  .join(",\n")}
} as const;
export type ThemeName = keyof typeof themes;
export type ThemeColours = (typeof themes)["light"];

/** Spacing/N → spacing["N"] in px (4 px grid). */
export const spacing = ${json(scale("Spacing/"))} as const;
export const radius = ${json(scale("Radius/"))} as const;
export const control = ${json(scale("Control/"))} as const;
export const avatar = ${json(scale("Avatar/"))} as const;
export const borderWidth = ${json(scale("Border/"))} as const;
export const fontSize = ${json(scale("Font Size/"))} as const;
export const lineHeight = ${json(scale("Line Height/"))} as const;

/** Figma text styles. */
export const textStyles = ${json(textStylesNative)} as const;

/** Figma elevation styles per theme. \`boxShadow\` for React Native 0.76+ and web; the shadow* props for older code (shadowRadius = Figma blur, as React Native Web draws it). */
export const shadows = {
${Object.entries(NATIVE_THEMES)
  .map(([k, mode]) => `  ${k}: ${json(shadowsFor(mode)).replace(/\n/g, "\n  ")}`)
  .join(",\n")}
} as const;
`;

const out = (rel: string, text: string) => {
  const p = resolve(root, rel);
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, text);
  console.log(`wrote ${rel}`);
};
out("src/styles/tokens.css", tokensCss);
out("src/styles/tailwind-theme.css", tailwindCss);
out("docs/tokens.md", md);
out("native/tokens.ts", nativeTs);
